import {terrainHeight,terrainName} from './terrain.js';
import {PLANS,WEAPONS,MODE_NAMES,padPoint} from './weapons.js';
const $=id=>document.getElementById(id),distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export function bindBuildControls(battle,clear){let allowed=()=>battle.status==='playing'&&$('pauseOverlay').classList.contains('hidden');for(let button of document.querySelectorAll('[data-craft]'))button.onclick=()=>{if(allowed())battle.choosePlan(button.dataset.craft);};$('command').onclick=()=>battle.cycleMode();$('openpad').onclick=()=>{if(allowed())battle.openPad();};$('jump').onclick=()=>{if(allowed())battle.jump();};$('use').onclick=()=>{if(allowed())battle.action();};$('switch').onclick=()=>{if(!allowed())return;clear();battle.switchUnit();};$('autoBuild').onclick=()=>{let b=battle.bases[battle.localTeam??0];b.autoPlan=!b.autoPlan;};addEventListener('keydown',e=>{if(e.code==='Tab'){e.preventDefault();if(battle.status==='playing'&&$('pauseOverlay').classList.contains('hidden')){clear();battle.switchUnit();}}if(e.code==='KeyR'&&!e.repeat&&allowed())battle.jump();if(e.code==='KeyF'&&!e.repeat&&battle.status==='playing'&&$('pauseOverlay').classList.contains('hidden'))battle.action();});}
export function updateBuildHUD(battle){document.querySelector("#playerhud .eyebrow").textContent="你的隊伍 · "+["藍兔","紅狐","黃貓","紫熊"][battle.localTeam??0];if(battle.localTeam!==undefined)$("objectiveText").textContent="連機對戰 · 搬箱回自己基地 · 暫停只停止你的操作";let p=battle.player,b=battle.bases[battle.localTeam??0],plan=PLANS[b.plan],atPad=p.hp>0&&distance(p,padPoint(b))<5;$('dropHint').textContent='隨機機甲／直昇機補給：'+Math.max(0,Math.ceil(battle.specialTimer))+' 秒';$('jump').textContent=p.vehicle==='helicopter'?'升高／降低 R':'跳躍 R';$('use').textContent=p.vehicle==='helicopter'?'降落／離機 F':p.tank?'離開載具 F':'使用／開箱 F';$('weapon').textContent=(p.super?'超級 ':'')+WEAPONS[p.weapon].name+(p.weapon==='fist'?'':' · '+p.ammo+' 發');$('switch').disabled=battle.alive(battle.localTeam??0).length<2;$('squad').textContent='隊伍 '+battle.alive(battle.localTeam??0).length+' / 4';$('stock').textContent=b.pad.length+' / 8 箱';$('padstatus').textContent=plan.name+' · '+b.pad.length+' / '+plan.slots.length+(battle.readyPad(b)?' · 可開箱':'');$('helperstatus').textContent=battle.alive(battle.localTeam??0).length<2?'目前只有你，先堆兩箱造隊友。':'隊友搬回 '+Math.max(0,battle.stats.teamDelivered-battle.stats.delivered)+' 箱 · '+MODE_NAMES[battle.mode];$('commandText').textContent=MODE_NAMES[battle.mode];$('buildhint').textContent=b.hp<=0?'基地已毀，不能再建造。':atPad?'F 開箱；E 將手上箱放入輪廓。':'隊友按所選形狀拾箱及堆箱，建成後在地面拾取。';$('buildpanel').style.opacity=1;$('openpad').disabled=!atPad||b.hp<=0||!battle.readyPad(b);$('autoBuild').textContent='自動計劃：'+(b.autoPlan?'開':'關');$('pad-preview').innerHTML=Array.from({length:8},(_,slot)=>{let c=b.pad.find(c=>c.slot===slot);return '<span class="'+(plan.slots.includes(slot)?'target ':'')+(c?'filled ':'')+(c?.super?'super':'')+'">'+(slot<4?'下':'上')+(slot%4+1)+(c?' ▣':' ◇')+'</span>';}).join('');for(let button of document.querySelectorAll('[data-craft]')){let kind=button.dataset.craft;button.classList.toggle('active',kind===b.plan);button.disabled=b.hp<=0||b.pad.some(c=>!PLANS[kind].slots.includes(c.slot))||(['buddy','elite'].includes(kind)&&battle.alive(battle.localTeam??0).length>=4);}document.querySelector('#fire b').textContent=p.carrying?'拋箱':p.weapon==='fist'?'拳擊':'射擊';$('terrain').textContent=terrainName(p.x,p.y)+' · 海拔 '+terrainHeight(p.x,p.y).toFixed(1)+' m';$('carry').textContent=p.carrying?'▣ 搬運中':p.hp<=0?'全隊倒下':'空手';$('interactText').textContent=p.carrying?(distance(p,padPoint(b))<4.5?'放入堆箱台':'放下箱子'):'拾起箱子';}
